-- Run in BEGIN / ROLLBACK. No application callbacks or real notifications sent.
do $$
declare u1 uuid=gen_random_uuid(); u2 uuid=gen_random_uuid(); outsider uuid=gen_random_uuid(); admin_id uuid=gen_random_uuid();
 g1 uuid; g2 uuid; ch uuid; p uuid=gen_random_uuid(); hidden uuid=gen_random_uuid(); comment_id uuid=gen_random_uuid(); bad boolean; stats record; baseline text;
begin
 select md5(string_agg(to_jsonb(x)::text,'' order by id)) into baseline from public.payments x;
 insert into auth.users(id,email,email_confirmed_at) values(u1,'wall1-'||u1||'@example.invalid',now()),(u2,'wall2-'||u2||'@example.invalid',now()),(outsider,'wall3-'||outsider||'@example.invalid',now()),(admin_id,'wall-admin-'||admin_id||'@example.invalid',now());
 insert into public.profiles(id,full_name,role) values(u1,'Ana Prueba','guardian'),(u2,'Luis Prueba','guardian'),(outsider,'Fuera Prueba','guardian'),(admin_id,'Admin Prueba','admin') on conflict(id) do update set full_name=excluded.full_name,role=excluded.role;
 insert into public.guardians(user_id,full_name,email,phone) values(u1,'Ana Prueba','wall1-'||u1||'@example.invalid','000000000') returning id into g1;
 insert into public.guardians(user_id,full_name,email,phone) values(u2,'Luis Prueba','wall2-'||u2||'@example.invalid','000000000') returning id into g2;
 insert into public.children(full_name,birth_date,birth_year) values('QA MURO ROLLBACK','2016-01-01',2016) returning id into ch;
 insert into public.child_guardians(child_id,guardian_id,relationship,is_primary) values(ch,g1,'Tutor',true),(ch,g2,'Tutor',false);
 insert into public.community_posts(id,author_user_id,child_id,body,visibility,status) values(p,u1,ch,'Logro ficticio QA','community','published'),(hidden,u1,ch,'Logro privado QA','private','published');
 perform set_config('request.jwt.claim.sub',u1::text,true);
 execute 'set local role authenticated';
 insert into public.community_post_likes(post_id,user_id) values(p,u1) on conflict do nothing;
 insert into public.community_post_likes(post_id,user_id) values(p,u1) on conflict do nothing;
 insert into public.community_post_comments(id,post_id,author_user_id,author_name,body) values(comment_id,p,u1,'FALSO ADMIN',' Enhorabuena ');
 if (select author_name from public.community_post_comments where id=comment_id)<>'Ana' then raise exception 'Author label spoofed'; end if;
 bad=false; begin insert into public.community_post_likes(post_id,user_id) values(hidden,u1); exception when insufficient_privilege then bad=true; end;
 if not bad then raise exception 'Private post accepted like'; end if;
 bad=false; begin insert into public.community_post_comments(post_id,author_user_id,body) values(hidden,u1,'Privado'); exception when insufficient_privilege then bad=true; end;
 if not bad then raise exception 'Private post accepted comment'; end if;
 insert into public.community_post_comments(post_id,author_user_id,body) values(p,u1,'Borrar propio');
 delete from public.community_post_comments where post_id=p and body='Borrar propio';
 if exists(select 1 from public.community_post_comments where post_id=p and body='Borrar propio') then raise exception 'Own delete failed'; end if;
 perform set_config('request.jwt.claim.sub',u2::text,true);
 insert into public.community_post_likes(post_id,user_id) values(p,u2);
 select * into stats from public.community_post_engagement(array[p]);
 if stats.likes<>2 or stats.comments<>1 or stats.liked is not true then raise exception 'Counts or like ownership wrong'; end if;
 delete from public.community_post_comments where id=comment_id;
 if not exists(select 1 from public.community_post_comments where id=comment_id) then raise exception 'Other user deleted comment'; end if;
 bad=false; begin insert into public.community_post_comments(post_id,author_user_id,body) values(p,u1,'Spoof'); exception when others then bad=true; end;
 if not bad then raise exception 'Comment owner spoof allowed'; end if;
 bad=false; begin update public.community_post_comments set author_user_id=u2 where id=comment_id; exception when insufficient_privilege then bad=true; end;
 if not bad then raise exception 'Comment update exposed'; end if;
 delete from public.community_post_likes where post_id=p and user_id=u2;
 select * into stats from public.community_post_engagement(array[p]);
 if stats.likes<>1 or stats.liked is not false then raise exception 'Unlike wrong'; end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if exists(select 1 from public.community_posts where id=p) or exists(select 1 from public.community_post_comments where post_id=p) or exists(select 1 from public.community_post_likes where post_id=p) then raise exception 'Unlinked signup sees community'; end if;
 bad=false; begin insert into public.community_post_likes(post_id,user_id) values(p,outsider); exception when insufficient_privilege then bad=true; end;
 if not bad then raise exception 'Unlinked signup interacts'; end if;
 execute 'reset role';
 if has_table_privilege('anon','public.community_post_comments','select') or has_function_privilege('anon','public.community_post_engagement(uuid[])','execute') then raise exception 'Anonymous access'; end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true); execute 'set local role authenticated';
 delete from public.community_post_comments where id=comment_id;
 if exists(select 1 from public.community_post_comments where id=comment_id) then raise exception 'Admin moderation failed'; end if;
 update public.community_posts set status='rejected' where id=p;
 perform set_config('request.jwt.claim.sub',u2::text,true);
 if exists(select 1 from public.community_post_engagement(array[p])) or exists(select 1 from public.community_post_likes where post_id=p) then raise exception 'Withdrawn content exposed'; end if;
 execute 'reset role';
 delete from public.community_posts where id=p;
 if exists(select 1 from public.community_post_likes where post_id=p) then raise exception 'Cascade failed'; end if;
 if (select md5(string_agg(to_jsonb(x)::text,'' order by id)) from public.payments x) is distinct from baseline then raise exception 'Payments changed'; end if;
 raise notice 'PASS likes, retries, comments, author labels, ownership, outsider/private/withdrawn isolation, admin moderation, cascade and unchanged payments';
end $$;
